sys_script_client.script:
function onSubmit() {
    var pendingTelco = g_form.getValue('x_g_sonc_ns_pro_pending_telco_provider');
    var pendingHostCircuit = g_form.getValue('x_g_sonc_ns_pro_pending_pe_host_circuit_id');

    var currentView = getView();
    currentView = currentView.toLowerCase();
	//alert(currentView);
    if (currentView == "proposedcircuits") {

		if (pendingTelco) {
			if (!pendingHostCircuit) {
				alert("When pending telco is populated you must select a new host circuit");
				g_form.setMandatory('x_g_sonc_ns_pro_pending_pe_host_circuit_id',true);
				return false;
			}
		}
	}
    return;
}
